        Scanner scn = new Scanner(System.in);
        int totalChars = scn.nextInt();
        String inputStr = scn.next();
        inputStr = inputStr.toLowerCase();
        int maxSegmentLength = -1;
        int totalWords = 0;
        int depth = 0;
        int underscoreRun = 0;
        for(int i=0; i<totalChars; i++){
