#include <iostream>
#include <string>
#include <algorithm>

int main() {
    int totalChars;
    std::cin >> totalChars;
    std::string inputStr;
    std::cin >> inputStr;
    for (auto &c : inputStr) c = tolower(c);

    int maxSegmentLength = -1;
    int totalWords = 0;
    int depth = 0;
    int underscoreRun = 0;

    for (int i = 0; i < totalChars; i++) {
        char ch = inputStr[i];
        if (ch == '(') {
            depth++;
            underscoreRun = 0;
        } else if (ch == ')') {
            if (depth == 1 && underscoreRun != 0) totalWords++;
            depth--;
            underscoreRun = 0;
        } else if (ch == '_') {
            if (depth == 1 && underscoreRun != 0) totalWords++;
            underscoreRun = 0;
        } else {
            underscoreRun++;
        }
        if (depth == 0) {
            maxSegmentLength = std::max(underscoreRun, maxSegmentLength);
        }
    }
    std::cout << maxSegmentLength << " " << totalWords << std::endl;
    return 0;
}
